package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;
@Entity@Table(name="spms_plan_assignment_objective",uniqueConstraints=@UniqueConstraint(name="uk_spms_assignment_objective",columnNames={"agency_id","assignment_id","objective_version_id"}))
public class PerformancePlanAssignmentObjective extends RspAuditedEntity{@Column(name="assignment_id",nullable=false,length=36)private String assignmentId;@Column(name="objective_version_id",nullable=false,length=36)private String objectiveVersionId;@Column(name="display_order",nullable=false)private int displayOrder;protected PerformancePlanAssignmentObjective(){}public PerformancePlanAssignmentObjective(String a,String assignment,String objective,int order){super(a);assignmentId=requiredText(assignment,"assignmentId");objectiveVersionId=requiredText(objective,"objectiveVersionId");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;}public String getAssignmentId(){return assignmentId;}public String getObjectiveVersionId(){return objectiveVersionId;}public int getDisplayOrder(){return displayOrder;}}
